#include <bits/stdc++.h>

#define sz(x) (int)(x.size())
#define FOR( i, x, n, d ) for( int i = x; i <= n; i += d )
#define FORR( i, x, n, d ) for( int i = x; i >= n; i -= d )

using namespace std;

const int N = (1 << 20) + 5;
const int mod = 1e9 + 7;

int n, m, c[N], dp[N], cnt[N], st[N][21];

void add(int &x, int y)
{
x += y;
if(x >= mod) x -= mod;
}
void solve()
{
cin >> n >> m;

FOR( i, 1, m, 1 )
{
cin >> c[i];
}
dp[0] = cnt[0] = 1;

FOR( i, 1, n, 1 )
{
st[i][0] = 0;

FOR( j, 0, 19, 1 )
{
st[i][j + 1] = st[i][j];
if(!((m >> j) & 1) || i < (1 << j)) continue;

else
{
add(st[i][j + 1], st[i - (1 << j)][j]);
add(st[i][j + 1], dp[i - (1 << j)]);
}
}
dp[i] = st[i][20];
}
FOR( i, 1, n, 1 )
{
st[i][0] = 0;

FOR( j, 0, 19, 1 )
{
st[i][j + 1] = st[i][j];
if(!((m >> j) & 1) || i < (1 << j)) continue;

else
{
add(st[i][j + 1], st[i - (1 << j)][j]);
add(st[i][j + 1], cnt[i - (1 << j)]);
}
}
cnt[i] = st[i][20];
add(cnt[i], dp[i]);
}
int ans = 0;

FOR( i, 1, m, 1 )
{
if((m & i) == i) add(ans, c[i] * 1ll * cnt[n - i] % mod);
}
cout << ans << '\n';
}
signed main()
{
ios_base::sync_with_stdio(0), cin.tie(0);

int t = 0;
if(!t) cin >> t;
while(t --) solve();
}

